export interface Supplier {
  supplierId: number;
  companyId: number;
  supplierName: string;
  contactName: string | null;
  phone: string | null;
  email: string | null;
  address: string | null;
  active: '1' | '0';
  created_At: string;
  updated_at: string | null;
}

export interface SupplierListResponse {
  suppliers: Supplier[];
}

// Omit fields handled by the backend or not present on creation
export type CreateSupplierRequest = Omit<Supplier, 'supplierId' | 'created_At' | 'updated_at'>;
export type UpdateSupplierRequest = Partial<Omit<Supplier, 'supplierId' | 'companyId' | 'created_At' | 'updated_at'>>; // companyId should not be updated via this endpoint

// GET ALL — POST /all_suppliers
export async function getAllSuppliers(companyId: number): Promise<Supplier[]> {
  const res = await fetch(BASE_URL + "/all_suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "companyId": companyId }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data: SupplierListResponse = await res.json();
  return data.suppliers ?? [];   // unwrap: SP wraps array under plural key
}

// CREATE — action: 1
export async function createSupplier(payload: CreateSupplierRequest): Promise<Supplier> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  return await res.json();
}

// UPDATE — action: 2
export async function updateSupplier(id: number, companyId: number, payload: UpdateSupplierRequest): Promise<Supplier> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 2, "supplierId": id, "companyId": companyId, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  return await res.json();
}

// DELETE — action: 3
export async function deleteSupplier(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/suppliers", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "suppliers": [{ "action": 3, "supplierId": id, "companyId": companyId }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
}
