import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../contexts/UserContext';
import {
  Supplier,
  getAllSuppliers,
  createSupplier,
  updateSupplier,
  deleteSupplier,
  CreateSupplierRequest,
  UpdateSupplierRequest
} from '../api/supplierApi';
import { InputInputEventDetail, SearchbarInputEventDetail, ToggleChangeEventDetail, InfiniteScrollCustomEvent } from '@ionic/core';

// UTC to Hermosillo (UTC-7) conversion helper
const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  // Append 'Z' if not present to ensure it's parsed as UTC
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Subtract 7 hours (7 * 60 minutes * 60 seconds * 1000 milliseconds)
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const PAGE_SIZE = 20; // Number of items to load per scroll

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();

  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [filteredSuppliers, setFilteredSuppliers] = useState<Supplier[]>([]);
  const [displayedSuppliers, setDisplayedSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [showCreateEditModal, setShowCreateEditModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentSupplier, setCurrentSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState<CreateSupplierRequest | Supplier>({
    companyId: companyId,
    supplierName: '',
    contactName: null,
    phone: null,
    email: null,
    address: null,
    active: '1',
  });
  const [formErrors, setFormErrors] = useState<{
    supplierName?: string;
    email?: string;
  }>({});
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [supplierToDelete, setSupplierToDelete] = useState<Supplier | null>(null);
  const [page, setPage] = useState(1);
  const [isInfiniteDisabled, setInfiniteDisabled] = useState(false);

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const validateForm = () => {
    const errors: typeof formErrors = {};
    if (!formState.supplierName.trim()) {
      errors.supplierName = 'El nombre del proveedor es requerido.';
    }
    if (formState.email && !/^[\w-.]+@([\w-]+\.)+[\w-]{2,4}$/.test(formState.email)) {
      errors.email = 'Ingrese un correo electrónico válido.';
    }
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const fetchSuppliers = async () => {
    if (!companyId) return;
    setLoading(true);
    try {
      const data = await getAllSuppliers(companyId);
      setSuppliers(data);
      setPage(1);
      setInfiniteDisabled(false);
    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al cargar proveedores.');
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchSuppliers();
  }, [companyId]);

  useEffect(() => {
    const lowerCaseSearchTerm = searchTerm.toLowerCase();
    const filtered = suppliers.filter(
      (s) =>
        s.supplierName.toLowerCase().includes(lowerCaseSearchTerm) ||
        (s.contactName?.toLowerCase().includes(lowerCaseSearchTerm) ?? false) ||
        (s.email?.toLowerCase().includes(lowerCaseSearchTerm) ?? false) ||
        (s.phone?.toLowerCase().includes(lowerCaseSearchTerm) ?? false)
    );
    setFilteredSuppliers(filtered);
    setDisplayedSuppliers(filtered.slice(0, PAGE_SIZE));
    setPage(1);
    setInfiniteDisabled(filtered.length <= PAGE_SIZE);
  }, [searchTerm, suppliers]);

  const loadMoreItems = (event: InfiniteScrollCustomEvent) => {
    const nextPage = page + 1;
    const newItems = filteredSuppliers.slice(0, nextPage * PAGE_SIZE);
    setDisplayedSuppliers(newItems);
    setPage(nextPage);
    if (newItems.length === filteredSuppliers.length) {
      setInfiniteDisabled(true);
    }
    event.detail.complete();
  };

  const handleOpenCreateModal = () => {
    setIsEditing(false);
    setCurrentSupplier(null);
    setFormState({
      companyId: companyId,
      supplierName: '',
      contactName: null,
      phone: null,
      email: null,
      address: null,
      active: '1',
    });
    setFormErrors({});
    setShowCreateEditModal(true);
  };

  const handleOpenEditModal = (supplier: Supplier) => {
    setIsEditing(true);
    setCurrentSupplier(supplier);
    setFormState(supplier);
    setFormErrors({});
    setShowCreateEditModal(true);
  };

  const handleModalDismiss = () => {
    setShowCreateEditModal(false);
    setCurrentSupplier(null);
  };

  const handleFormChange = (key: keyof (CreateSupplierRequest | Supplier), value: string | boolean | null) => {
    setFormState((prev) => ({
      ...prev,
      [key]: typeof value === 'boolean' ? (value ? '1' : '0') : value,
    }));
    // Clear error for the field being edited
    if (formErrors[key as keyof typeof formErrors]) {
      setFormErrors((prev) => ({ ...prev, [key]: undefined }));
    }
  };

  const handleSaveSupplier = async () => {
    if (!validateForm()) {
      return;
    }

    setSaving(true);
    setError('');
    try {
      if (isEditing && currentSupplier) {
        // Omit companyId for update payload as it's passed separately
        const payload: UpdateSupplierRequest = { ...formState as Supplier };
        delete payload.companyId;
        delete (payload as any).created_At; // Remove generated fields from payload
        delete (payload as any).updated_at; // Remove generated fields from payload

        await updateSupplier(currentSupplier.supplierId, companyId, payload);
        // We don't need to explicitly update `currentSupplier.updated_at` here, refetch will handle it.
      } else {
        await createSupplier(formState as CreateSupplierRequest);
      }
      setShowCreateEditModal(false);
      fetchSuppliers();
      setError('Proveedor guardado exitosamente.');
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar el proveedor.');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteClick = (supplier: Supplier) => {
    setSupplierToDelete(supplier);
    setShowDeleteAlert(true);
  };

  const confirmDelete = async () => {
    if (!supplierToDelete) return;
    setLoading(true);
    setError('');
    try {
      await deleteSupplier(supplierToDelete.supplierId, companyId);
      fetchSuppliers();
      setError('Proveedor eliminado exitosamente.');
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar el proveedor.');
    } finally {
      setLoading(false);
      setSupplierToDelete(null);
      setShowDeleteAlert(false);
    }
  };

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonLoading isOpen={loading} message="Cargando proveedores..." />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color={error.toLowerCase().includes('error') ? 'danger' : 'success'}
        />

        <IonToolbar className="supplier-toolbar">
          <IonSearchbar
            value={searchTerm}
            onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchTerm(e.detail.value!)}
            placeholder="Buscar proveedor..."
            debounce={300}
            className="supplier-searchbar"
          />
          <IonButton fill="solid" slot="end" onClick={handleOpenCreateModal} className="supplier-add-button">
            <IonIcon icon={add} slot="start" />
            Nuevo Proveedor
          </IonButton>
        </IonToolbar>

        <IonList className="supplier-list">
          {displayedSuppliers.length === 0 && !loading && searchTerm === '' && (
            <IonItem>
              <IonLabel>No hay proveedores registrados.</IonLabel>
