                  {supplier.active === '1' ? 'Activo' : 'Inactivo'}
                </IonLabel>
              </IonLabel>
              <IonButton fill="clear" color="medium" onClick={() => handleOpenEditModal(supplier)} slot="end">
                <IonIcon icon={pencil} />
